def algorithm(func, dim, lb, ub, budget, rng):
    pop_size = int(np.sqrt(budget))
    x_best = np.full(dim, (ub - lb) * rng.uniform(0, 1) + lb)
    f_best = func(x_best)

    for _ in range(pop_size):
        child = x_best.copy()
        for i in range(dim):
            if rng.random() < 0.01:
                child[i] += (ub - lb) * rng.uniform(-1, 1) + lb
            elif rng.random() < 0.02:
                child[i] = rng.uniform(lb, ub)

        f_child = func(child)
        if f_child < f_best:
            x_best = child
            f_best = f_child

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = np.random.uniform(lb, ub, (1, dim))[0]
    best_x = x.copy()
    best_f = func(x)

    for i in range(budget):
        z = np.zeros(dim)
        for j in range(dim):
            p1, p2, p3 = rng.choice(best_x), rng.choice(best_x), rng.choice(best_x)
            z[j] = (p1 + p2 + p3) / 3 + rng.uniform(-1, 1) * (best_x[j] - p1)
        x = clip(z)

        f = func(x)

        if f < best_f:
            best_f = f
            best_x = x.copy()

    return best_x
